/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 t=f.read_text(); pages=re.split(r'--- page (\\d+) ---',t)
 print('\\nFILE',f.name[:-4])
 for i in range(1,len(pages),2):
  s=' '.join(pages[i+1].split())
  for m in re.finditer(r'most.{0,25}fav|favou?rabl|lowest|lower.{0,25}(price|rate)|other customers|other distributors|no greater|no higher|best.{0,20}(price|term)|same.{0,30}(price|rate)',s,re.I): print('PAGE',pages[i],s[max(0,m.start()-220):m.end()+380])
PY"

